"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7770],{70449:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"MinigameData","desc":"The minigame registry. Built once at require time and frozen, it is the single\\nsource of truth for which modes and maps exist.\\n\\n### Modes\\n\\nEvery ModuleScript under `Features/Minigames/GameModes` is required and keyed\\nby its `config.name` \u2014 **not** by its module name, which is why\\n[VotePoolItem].gameMode carries a display name rather than a path. Modules with\\nno config, or with `config.disabled` set, are skipped, so a mode is taken out\\nof rotation by flipping one field rather than by moving the file.\\n\\nMissing `maps` is an assertion rather than a skip: a mode that has been written\\nbut cannot be played is a mistake worth failing loudly on.\\n\\n### Maps\\n\\nEvery Model under `ServerStorage.Maps` is registered, keyed by its\\n`Config.displayName` if it has one and its instance name otherwise. Each map\\nmust have a `Spawns` child \u2014 asserted, since a map without spawns cannot be\\nplayed. Its `Config` Configuration is flattened into the map record (both value\\nobjects and attributes), a map with no `Config` is warned about and dropped,\\nand a missing thumbnail falls back to a placeholder with a note.\\n\\nTwo frozen tables come out: `modes` (`name \u2192 GameMode`) and `maps`\\n(`name \u2192 Map`).\\n\\nGated by [FeatureFlags].Minigames \u2014 disabled by default; per-project forks\\nenable it deliberately. With the flag off the module returns immediately with\\nboth tables empty and frozen, so no mode module is ever required and no map is\\nvalidated. Callers see an empty registry rather than an error.","tags":["dormant"],"realm":["Server"],"source":{"line":40,"path":"src/Server/Features/Minigames/MinigameData.luau"}}')}}]);